package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.File;
import java.math.*;
import java.util.*;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveEntry_equals_TriageGen2Test {

    @Test
    public void testEquals_SameInstance() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        // Covers: if (this == obj) return true;
        assertTrue(entry.equals(entry));
    }

    @Test
    public void testEquals_NullObject() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        // Covers: if (obj == null || getClass() != obj.getClass()) return false;
        assertFalse(entry.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        Object other = "not a zip entry";
        // Covers: if (obj == null || getClass() != obj.getClass()) return false;
        assertFalse(entry.equals(other));
    }

    @Test
    public void testEquals_NullName_OtherNameNotNull() {
        // Using a subclass or reflection might be needed if getName() cannot be null, 
        // but based on the provided code, we test the logic path.
        // We need a way to make getName() return null. 
        // Since we cannot easily mock the final-like behavior without PowerMock, 
        // we assume the constructor or internal state allows it.
        ZipArchiveEntry entry = new ZipArchiveEntry(null);
        ZipArchiveEntry other = new ZipArchiveEntry("other.txt");

        // Covers: if (myName == null) { if (otherName != null) return false; }
        assertFalse(entry.equals(other));
    }

    @Test
    public void testEquals_NullName_OtherNameNull() {
        ZipArchiveEntry entry = new ZipArchiveEntry(null);
        ZipArchiveEntry other = new ZipArchiveEntry(null);

        // Covers: if (myName == null) { if (otherName != null) return false; } -> returns true
        assertTrue(entry.equals(other));
    }

    @Test
    public void testEquals_NameNotNull_TriggersElseIf() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        ZipArchiveEntry other = new ZipArchiveEntry("test.txt");

        // The provided code has a suspicious logic:
        // else if (!false) { return false; }
        // Since !false is always true, this branch will always return false if myName != null.
        // This test captures that specific logic path.
        assertFalse(entry.equals(other));
    }
}
